import { Ionicons } from '../components/Ionicons';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Image, Platform, Pressable, SafeAreaView, ScrollView, Share, StyleSheet, Text, TextInput, View, useWindowDimensions } from 'react-native';
import type { ReportStatus } from '../types/report';
import type { AdminRole, StaffMember, UserAccount } from '../services/admin';
import type { Report } from './CitizenSecondaryScreens';
import OsmMap from './OsmMap';

const C = { dark: '#06291A', green: '#0E5232', soft: '#EAF5EF', bg: '#F4F6F7', ink: '#14181A', text: '#47525A', muted: '#657078', border: '#D5DADD', white: '#FFF', red: '#B3261E', redSoft: '#FCECEB', gold: '#A56F13', goldSoft: '#FBF3DF', blueSoft: '#EAF2F8' };
type Page = 'Overview' | 'Reports' | 'Map' | 'Analytics' | 'Settings';
type CaseStatus = Exclude<ReportStatus, 'Draft'>;
type Filter = 'All' | CaseStatus;
type Summary = { counts: Record<string, number>; total: number; awaiting: number; mapped: number };
type Props = { reports: Report[]; loading: boolean; error: string; adminId: string; adminEmail?: string | null; staffRole: Exclude<AdminRole, 'citizen'>; staffDirectory: StaffMember[]; userDirectory: UserAccount[]; onUpdateStatus: (id: string, status: ReportStatus, adminId: string, reviewNote?: string) => Promise<void>; onAssignReport: (id: string, inspector: string, adminId: string) => Promise<void>; onRequestClarification: (id: string, message: string, adminId: string) => Promise<void>; onSubmitFindings: (id: string, findings: { observation: string; severity: string; action: string; evidenceUrl?: string | null }, inspectorId: string) => Promise<void>; onAnalyseEvidence: (id: string, evidenceUrl: string) => Promise<void>; onCreateReport: () => void; onSignOut: () => void };

const filters: Filter[] = ['All', 'Submitted', 'Under Review', 'Verified', 'Assigned', 'Resolved', 'Rejected'];
const navItems: Array<[Page, keyof typeof Ionicons.glyphMap]> = [['Overview', 'grid-outline'], ['Reports', 'document-text-outline'], ['Map', 'map-outline'], ['Analytics', 'bar-chart-outline'], ['Settings', 'settings-outline']];
const ref = (r: Report) => `LW-${r.id.slice(0, 6).toUpperCase()}`;
const location = (r: Report, precision = 4) => r.locationName?.trim() || (r.latitude != null && r.longitude != null ? `${r.latitude.toFixed(precision)}, ${r.longitude.toFixed(precision)}` : 'Location not available');
const date = (r: Report) => { const value = r.createdAt?.toDate?.(); return value instanceof Date && !Number.isNaN(value.getTime()) ? value.toLocaleDateString(undefined, { day: '2-digit', month: 'short', year: 'numeric' }) : 'Date unavailable'; };

export function AdminScreen({ reports, loading, error, adminId, adminEmail, staffRole, staffDirectory, userDirectory, onUpdateStatus, onAssignReport, onRequestClarification, onSubmitFindings, onAnalyseEvidence, onCreateReport, onSignOut }: Props) {
  const [page, setPage] = useState<Page>('Overview');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [directoryOpen, setDirectoryOpen] = useState(false);
  const [filter, setFilter] = useState<Filter>('All');
  const [search, setSearch] = useState('');
  const desktop = useWindowDimensions().width >= 900;
  const selected = useMemo(() => reports.find(r => r.id === selectedId) ?? null, [reports, selectedId]);
  const summary = useMemo<Summary>(() => {
    const counts: Record<string, number> = {};
    reports.forEach(r => { counts[r.status] = (counts[r.status] ?? 0) + 1; });
    return { counts, total: reports.length, awaiting: reports.filter(r => !['Draft', 'Resolved', 'Rejected'].includes(r.status)).length, mapped: reports.filter(r => r.latitude != null && r.longitude != null).length };
  }, [reports]);
  const visible = useMemo(() => {
    const query = search.trim().toLowerCase();
    return reports.filter(r => {
      const haystack = [r.id, ref(r), r.category, r.description, r.locationName, r.status].filter(Boolean).join(' ').toLowerCase();
      return (filter === 'All' || r.status === filter) && haystack.includes(query);
    });
  }, [reports, filter, search]);
  const navigate = (next: Page) => { setSelectedId(null); setPage(next); };
  const openReport = (r: Report) => { setSelectedId(r.id); setPage('Reports'); };

  return <SafeAreaView style={s.safe}>
    <Header desktop={desktop} page={page} role={staffRole} onSignOut={onSignOut} onSearch={() => navigate('Reports')} onNotifications={() => navigate('Reports')} />
    <View style={[s.body, desktop && s.bodyWide]}>
      <Navigation desktop={desktop} page={page} role={staffRole} navigate={navigate} onSignOut={onSignOut} />
      <View style={s.main}>
        {!desktop && <MobileNavigation page={page} navigate={navigate} />}
        <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={[s.page, !desktop && s.pageMobile]}>
          {selected ? <Review report={selected} staffRole={staffRole} staffDirectory={staffDirectory} adminId={adminId} onBack={() => setSelectedId(null)} onUpdateStatus={(status, note) => onUpdateStatus(selected.id, status, adminId, note)} onAssign={(inspector) => onAssignReport(selected.id, inspector, adminId)} onRequestClarification={(message) => onRequestClarification(selected.id, message, adminId)} onSubmitFindings={(findings) => onSubmitFindings(selected.id, findings, adminId)} onAnalyseEvidence={() => onAnalyseEvidence(selected.id, selected.evidenceUrl ?? '')} />
            : page === 'Overview' ? <Overview reports={reports} loading={loading} error={error} summary={summary} role={staffRole} openReport={openReport} navigate={navigate} />
            : page === 'Reports' ? <ReportsInteractive reports={visible} total={reports.length} summary={summary} loading={loading} error={error} filter={filter} setFilter={setFilter} search={search} setSearch={setSearch} openReport={openReport} onCreateReport={onCreateReport} canCreateReport={staffRole === 'admin'} />
            : page === 'Map' ? <MapInteractive reports={reports} openReport={openReport} />
            : page === 'Analytics' ? <AnalyticsDashboard reports={reports} summary={summary} openReport={openReport} navigate={navigate} />
            : <SettingsDashboard adminId={adminId} adminEmail={adminEmail} role={staffRole} navigate={navigate} onOpenDirectory={() => setDirectoryOpen(true)} />}
          <Footer />
        </ScrollView>
      </View>
    </View>
    {directoryOpen && <View style={s.directoryOverlay}><Pressable accessibilityRole="button" accessibilityLabel="Close user directory" onPress={() => setDirectoryOpen(false)} style={[s.directoryBackdrop, desktop ? s.directoryBackdropDesktop : s.directoryBackdropMobile]} /><View style={[s.directoryModal, desktop ? s.directoryModalDesktop : s.directoryModalMobile]}><View style={s.directoryModalHeader}><View><Text style={s.directoryModalEyebrow}>ADMINISTRATION</Text><Text style={s.directoryModalTitle}>Workspace accounts</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Close user directory" onPress={() => setDirectoryOpen(false)} style={s.directoryClose}><Ionicons name="close" size={21} color={C.text} /></Pressable></View><ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={s.directoryModalContent}><UserDirectory users={userDirectory} /></ScrollView></View></View>}
  </SafeAreaView>;
}

function Header({ desktop, page, role, onSignOut, onSearch, onNotifications }: { desktop: boolean; page: Page; role: Exclude<AdminRole, 'citizen'>; onSignOut: () => void; onSearch: () => void; onNotifications: () => void }) {
  const label = role === 'admin' ? 'Administrator' : 'Investigator / Field officer';
  const currentPage = page === 'Overview' ? (role === 'admin' ? 'Overview' : 'My workspace') : page;
  return <View style={{ height: 64, backgroundColor: C.white, borderBottomWidth: 1, borderBottomColor: C.border, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: desktop ? 30 : 18 }}>
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><Ionicons name="grid-outline" size={17} color={C.green} /><Text style={{ color: C.text, fontSize: 12 }}>Dashboard</Text><Ionicons name="chevron-forward" size={13} color={C.muted} /><Text style={{ color: C.muted, fontSize: 12 }}>{role === 'admin' ? 'Case management' : 'Field operations'}</Text><Ionicons name="chevron-forward" size={13} color={C.muted} /><Text style={{ color: C.ink, fontSize: 12, fontWeight: '700' }}>{currentPage}</Text></View>
    {desktop && <View style={{ position: 'absolute', right: 300, flexDirection: 'row', gap: 8 }}><Pressable accessibilityRole="button" accessibilityLabel="Search reports" onPress={onSearch} style={{ width: 250, height: 38 }} /><Pressable accessibilityRole="button" accessibilityLabel="Open report notifications" onPress={onNotifications} style={{ width: 28, height: 38 }} /></View>}
    {desktop ? <View style={{ flexDirection: 'row', alignItems: 'center', gap: 18 }}><View style={{ width: 250, height: 38, borderWidth: 1, borderColor: C.border, borderRadius: 7, flexDirection: 'row', alignItems: 'center', paddingHorizontal: 12, gap: 8 }}><Ionicons name="search-outline" size={17} color={C.muted} /><Text style={{ color: C.muted, fontSize: 12 }}>Search reports, cases…</Text></View><Ionicons name="notifications-outline" size={20} color={C.muted} /><View style={{ backgroundColor: C.soft, borderRadius: 18, paddingHorizontal: 12, paddingVertical: 8, flexDirection: 'row', alignItems: 'center', gap: 6 }}><Ionicons name="shield-checkmark-outline" size={15} color={C.green} /><Text style={{ color: C.green, fontSize: 11, fontWeight: '700' }}>{label}</Text></View></View> : <Pressable accessibilityRole="button" accessibilityLabel="Sign out" hitSlop={10} onPress={onSignOut}><Ionicons name="log-out-outline" size={21} color={C.green} /></Pressable>}
  </View>;
}

function Navigation({ desktop, page, role, navigate, onSignOut }: { desktop: boolean; page: Page; role: Exclude<AdminRole, 'citizen'>; navigate: (page: Page) => void; onSignOut: () => void }) {
  if (!desktop) return null;
  const accountLabel = role === 'admin' ? 'Ministry administrator' : 'Investigator / Field officer';
  return <View style={[s.sidebar, { backgroundColor: C.dark, borderRightWidth: 0, padding: 18 }]}>
    <View style={{ paddingHorizontal: 10, paddingVertical: 12, marginBottom: 22 }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}><View style={{ width: 34, height: 34, borderRadius: 9, backgroundColor: C.soft, alignItems: 'center', justifyContent: 'center' }}><Image source={require('../../coat-of-arms-transparent.png')} style={{ width: 24, height: 24 }} resizeMode="contain" /></View><View><Text style={{ color: C.white, fontSize: 16, fontWeight: '700' }}>LandWatch ZW</Text><Text style={{ color: '#B7D5C5', fontSize: 10, marginTop: 2 }}>Ministry operations centre</Text></View></View></View>
    <Text style={{ color: '#B7D5C5', fontSize: 10, fontWeight: '700', letterSpacing: 1.1, marginHorizontal: 10, marginBottom: 10 }}>WORKSPACE</Text>
    {navItems.map(([item, icon]) => <Pressable key={item} accessibilityRole="tab" accessibilityState={{ selected: page === item }} onPress={() => navigate(item)} style={({ pressed }) => [{ minHeight: 46, borderRadius: 7, paddingHorizontal: 12, flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 5 }, page === item && { backgroundColor: '#1B6A46' }, pressed && s.pressed]}><Ionicons name={icon} size={19} color={page === item ? C.white : '#B7D5C5'} /><Text style={{ color: page === item ? C.white : '#B7D5C5', fontSize: 13, fontWeight: page === item ? '700' : '500' }}>{item}</Text></Pressable>)}
    <View style={{ flex: 1 }} />
    <View style={{ borderTopWidth: 1, borderTopColor: 'rgba(255,255,255,.16)', paddingTop: 18, paddingHorizontal: 10 }}><Text style={{ color: '#B7D5C5', fontSize: 10, fontWeight: '700', letterSpacing: 1 }}>ACCOUNT</Text><Text style={{ color: C.white, fontSize: 13, marginTop: 10 }}>{accountLabel}</Text><Text style={{ color: '#B7D5C5', fontSize: 10, marginTop: 4 }}>Protected workspace</Text><Pressable accessibilityRole="button" accessibilityLabel="Sign out of Ministry workspace" onPress={onSignOut} style={({ pressed }) => [{ flexDirection: 'row', alignItems: 'center', gap: 7, minHeight: 44, marginTop: 14 }, pressed && s.pressed]}><Ionicons name="log-out-outline" size={18} color="#FFB4AB" /><Text style={{ color: '#FFB4AB', fontSize: 12, fontWeight: '700' }}>Sign out</Text></Pressable></View>
  </View>;
}

function MobileNavigation({ page, navigate }: { page: Page; navigate: (page: Page) => void }) {
  return <View style={s.mobileNav}>{navItems.map(([item, icon]) => <Pressable key={item} accessibilityRole="tab" accessibilityState={{ selected: page === item }} onPress={() => navigate(item)} style={({ pressed }) => [s.mobileItem, page === item && s.mobileActive, pressed && s.pressed]}><Ionicons name={icon} size={19} color={page === item ? C.green : C.muted} /><Text style={[s.mobileText, page === item && s.mobileTextActive]} numberOfLines={1}>{item}</Text></Pressable>)}</View>;
}

function Heading({ eyebrow, title, subtitle }: { eyebrow: string; title: string; subtitle: string }) {
  return <View style={s.heading}><View style={s.headingCopy}><Text style={s.eyebrow}>{eyebrow}</Text><Text style={s.title}>{title}</Text><Text style={s.subtitle}>{subtitle}</Text></View><View style={s.live}><View style={s.liveDot} /><Text style={s.liveText}>Live data</Text></View></View>;
}

function Stats({ summary }: { summary: Summary }) {
  const data: Array<[string, number, keyof typeof Ionicons.glyphMap]> = [['Total reports', summary.total, 'documents-outline'], ['Awaiting action', summary.awaiting, 'time-outline'], ['Resolved', summary.counts.Resolved ?? 0, 'checkmark-circle-outline'], ['Mapped cases', summary.mapped, 'location-outline']];
  return <View style={s.stats}>{data.map(([label, value, icon]) => <View key={label} style={s.stat}><View style={s.statIcon}><Ionicons name={icon} size={19} color={C.green} /></View><Text style={s.statValue}>{value}</Text><Text style={s.statLabel}>{label}</Text></View>)}</View>;
}

function Overview({ reports, loading, error, summary, role, openReport, navigate }: { reports: Report[]; loading: boolean; error: string; summary: Summary; role: Exclude<AdminRole, 'citizen'>; openReport: (r: Report) => void; navigate: (p: Page) => void }) {
  const recent = reports.filter(r => r.status !== 'Draft').slice(0, 4);
  const investigator = role === 'inspector';
  if (!investigator) return <AdminCommandOverview reports={reports} loading={loading} error={error} summary={summary} openReport={openReport} navigate={navigate} />;
  return <><Heading eyebrow={investigator ? 'FIELD OPERATIONS' : 'MINISTRY OVERVIEW'} title={investigator ? 'Investigator workspace' : 'Case management'} subtitle={investigator ? 'Review assigned cases, record findings and keep field work traceable.' : 'Oversee, assign and track citizen-reported cases within the Ministry workflow.'} /><Stats summary={summary} />{error ? <ErrorState message={error} /> : null}<View style={s.overviewGrid}><View style={s.overviewColumn}><SectionHeader title={investigator ? 'Assigned cases' : 'Priority queue'} hint={investigator ? 'Cases requiring your field attention' : 'Latest reports awaiting Ministry attention'} action="View all" onPress={() => navigate('Reports')} />{loading ? <Loading label="Loading assigned cases…" /> : recent.length ? recent.map(r => <ReportCard key={r.id} report={r} onPress={() => openReport(r)} />) : <Empty icon="folder-open-outline" title="No assigned cases" text={investigator ? 'New assignments will appear here.' : 'New citizen reports will appear here.'} />}</View><View style={s.overviewColumn}><SectionHeader title={investigator ? 'Field location monitor' : 'Location monitor'} hint="Cases with usable coordinates" action="Open map" onPress={() => navigate('Map')} /><OsmMap height={310} reports={reports} /></View></View></>;
}

function AdminCommandOverview({ reports, loading, error, summary, openReport, navigate }: { reports: Report[]; loading: boolean; error: string; summary: Summary; openReport: (r: Report) => void; navigate: (p: Page) => void }) {
  const urgent = reports.filter(r => priorityFor(r) === 'Critical' || r.status === 'Submitted').slice(0, 3);
  const resolved = summary.counts.Resolved ?? 0;
  const active = (summary.counts.Assigned ?? 0) + (summary.counts['Under Review'] ?? 0) + (summary.counts.Verified ?? 0);
  const other = Math.max(0, summary.total - resolved - active);
  const systemStatus = error ? 'SYSTEM STATUS: ATTENTION REQUIRED' : loading ? 'SYSTEM STATUS: SYNCING DATA' : 'SYSTEM STATUS: OPERATIONAL';
  return <>
    <View style={s.commandHero}><View style={[s.heroBadge, { backgroundColor: C.green }]}><View style={s.liveDot} /><Text style={s.heroBadgeText}>{systemStatus}</Text></View><Text style={s.heroTitle}>Institutional Command Overview</Text><Text style={s.heroSubtitle}>Real-time monitoring of citizen reports and field operations across all administrative districts.</Text><View style={s.heroActions}><Pressable onPress={() => navigate('Reports')} style={[s.heroPrimary, { backgroundColor: C.green }]}><Ionicons name="shield-checkmark-outline" size={15} color={C.white} /><Text style={s.heroPrimaryText}>Review Urgent Alerts</Text></Pressable><Pressable onPress={() => navigate('Analytics')} style={[s.heroSecondary, { backgroundColor: C.soft }]}><Text style={[s.heroSecondaryText, { color: C.green }]}>Open Analytics</Text></Pressable></View></View>
    <Stats summary={summary} />{error ? <ErrorState message={error} /> : null}
    <View style={s.commandGrid}><View style={s.commandMapColumn}><View style={s.commandSectionHeader}><View><Text style={s.commandSectionTitle}>Geographic Case Distribution</Text><Text style={s.commandSectionHint}>Real-time heat map of active field investigations</Text></View><View style={s.mapControls}><Text style={s.mapControlActive}>All districts</Text><Text style={s.mapControl}>Hotspots</Text><Pressable onPress={() => navigate('Map')} style={s.mapFilter}><Ionicons name="options-outline" size={14} color={C.text} /><Text style={s.mapFilterText}>Filters</Text></Pressable></View></View><View style={s.commandMap}><OsmMap height={430} reports={reports} /><View style={s.mapLegend}><Text style={s.legendTitle}>MAP LEGEND</Text><LegendDot color={C.red} label="High priority cluster" /><LegendDot color="#1680C4" label="Routine field work" /><LegendDot color="#AEB7BD" label="Regional boundary" /></View></View></View><View style={s.commandSide}><Text style={s.commandSectionTitle}>Urgent Reports</Text><Text style={s.commandSectionHint}>Cases requiring immediate review</Text>{loading ? <Loading label="Loading alerts…" /> : urgent.length ? urgent.map(r => <Pressable key={r.id} onPress={() => openReport(r)} style={s.urgentCard}><View style={s.urgentTop}><Text style={s.urgentId}>{ref(r)}</Text><StatusBadge status={r.status} /></View><Text style={s.urgentTitle} numberOfLines={1}>{r.category}</Text><View style={s.urgentMeta}><Ionicons name="location-outline" size={12} color={C.muted} /><Text style={s.urgentMetaText} numberOfLines={1}>{location(r)}</Text></View></Pressable>) : <Empty compact icon="checkmark-circle-outline" title="No urgent reports" text="The queue is currently clear." />}<Pressable onPress={() => navigate('Reports')} style={s.viewPriority}><Text style={s.viewPriorityText}>VIEW ALL PRIORITY CASES</Text><Ionicons name="arrow-forward" size={15} color={C.green} /></Pressable><View style={s.healthCard}><Text style={s.commandSectionTitle}>Resolution Health</Text><Text style={s.commandSectionHint}>Performance across categories</Text><View style={s.healthRing}><View style={s.healthRingInner}><Text style={s.healthPercent}>{summary.total ? `${Math.round(resolved / summary.total * 100)}%` : '0%'}</Text><Text style={s.healthCaption}>resolved</Text></View></View><View style={s.healthLegend}><LegendDot color={C.green} label={`Resolved ${resolved}`} /><LegendDot color="#0D2E68" label={`Active ${active}`} /><LegendDot color={C.red} label={`Other ${other}`} /></View></View></View></View>
    <View style={s.bottomPanels}><View style={s.trendCard}><View style={s.commandSectionHeader}><View><Text style={s.commandSectionTitle}>Submission Volume Trends</Text><Text style={s.commandSectionHint}>Daily volume of incoming reports by status</Text></View><View style={s.periodPill}><Ionicons name="calendar-outline" size={13} color={C.muted} /><Text style={s.periodText}>Last 7 Days</Text></View></View><View style={s.trendBars}>{[38, 52, 42, 68, 48, 24, 19].map((height, index) => <View key={index} style={s.trendDay}><View style={s.trendBarTrack}><View style={[s.trendBar, { height }]} /><View style={[s.trendBarAlt, { height: Math.max(12, height * .58) }]} /></View><Text style={s.trendLabel}>{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][index]}</Text></View>)}</View></View><View style={s.efficiencyCard}><Text style={s.commandSectionTitle}>Officer Efficiency</Text><Text style={s.commandSectionHint}>Average field response turnaround</Text><EfficiencyRow label="Initial review time" value="1.2 hours" width="88%" color={C.green} /><EfficiencyRow label="On-site arrival" value="4.8 hours" width="62%" color="#1680C4" /><EfficiencyRow label="Investigation duration" value="24.5 hours" width="47%" color="#718AB5" /></View></View>
  </>;
}

function LegendDot({ color, label }: { color: string; label: string }) { return <View style={s.legendRow}><View style={[s.legendDot, { backgroundColor: color }]} /><Text style={s.legendText}>{label}</Text></View>; }
function EfficiencyRow({ label, value, width, color }: { label: string; value: string; width: string; color: string }) { return <View style={s.efficiencyRow}><View style={s.efficiencyLabel}><Text style={s.efficiencyName}>{label.toUpperCase()}</Text><Text style={s.efficiencyValue}>{value}</Text></View><View style={s.efficiencyTrack}><View style={[s.efficiencyFill, { width, backgroundColor: color }]} /></View></View>; }

function SectionHeader({ title, hint, action, onPress }: { title: string; hint: string; action: string; onPress: () => void }) {
  return <View style={s.rowTitle}><View style={s.headingCopy}><Text style={s.sectionTitle}>{title}</Text><Text style={s.sectionHint}>{hint}</Text></View><Pressable accessibilityRole="button" onPress={onPress}><Text style={s.link}>{action}</Text></Pressable></View>;
}

function exportReports(reports: Report[]) {
  const escape = (value: unknown) => `"${String(value ?? '').replace(/"/g, '""')}"`;
  const csv = [['Reference', 'Category', 'Status', 'Priority', 'Location', 'Date', 'Investigator'], ...reports.map(r => [ref(r), r.category, r.status, priorityFor(r), location(r), date(r), r.assignedInspector ?? ''])].map(row => row.map(escape).join(',')).join('\n');
  if (Platform.OS === 'web' && typeof document !== 'undefined') {
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a'); link.href = url; link.download = 'landwatch-cases.csv'; link.click(); URL.revokeObjectURL(url);
    return;
  }
  void Share.share({ title: 'LandWatch case export', message: csv });
}

function ReportsInteractive({ reports, total, summary, loading, error, filter, setFilter, search, setSearch, openReport, onCreateReport, canCreateReport }: { reports: Report[]; total: number; summary: Summary; loading: boolean; error: string; filter: Filter; setFilter: (f: Filter) => void; search: string; setSearch: (v: string) => void; openReport: (r: Report) => void; onCreateReport: () => void; canCreateReport: boolean }) {
  const [category, setCategory] = useState('All categories');
  const [openMenu, setOpenMenu] = useState<'status' | 'category' | null>(null);
  const [page, setPage] = useState(1);
  const [notice, setNotice] = useState('');
  const categories = ['All categories', ...Array.from(new Set(reports.map(r => r.category).filter(Boolean)))];
  const filtered = category === 'All categories' ? reports : reports.filter(r => r.category === category);
  const pageSize = 6;
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const pageReports = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const changeFilter = (next: Filter) => { setFilter(next); setPage(1); };
  const changeSearch = (value: string) => { setSearch(value); setPage(1); };
  const clearAll = () => { setSearch(''); setFilter('All'); setCategory('All categories'); setPage(1); };
  const pendingAssignment = reports.filter(r => r.status === 'Submitted' && !r.assignedInspector).length;
  const activeInvestigations = reports.filter(r => ['Under Review', 'Verified', 'Assigned'].includes(r.status)).length;
  const critical = reports.filter(r => !['Resolved', 'Rejected'].includes(r.status) && priorityFor(r) === 'Critical').length;
  return <>
    <View style={[s.caseHeading, s.caseHeadingResponsive]}><View style={s.headingCopy}><Text style={s.caseTitle}>Case Management</Text><Text style={s.caseSubtitle}>Oversee, assign, and track all citizen-reported cases within the Ministry jurisdiction.</Text></View>{canCreateReport && <Pressable accessibilityRole="button" onPress={onCreateReport} style={[s.createCase, s.createCaseResponsive]}><Ionicons name="add" size={17} color={C.white} /><Text style={s.createCaseText}>Create Report</Text></Pressable>}</View>
    <View style={s.caseStats}><CaseStat icon="documents-outline" label="Total cases" value={summary.total} /><CaseStat icon="person-add-outline" label="Pending assignment" value={pendingAssignment} /><CaseStat icon="location-outline" label="Active investigations" value={activeInvestigations} /><CaseStat icon="warning-outline" label="Critical escalations" value={String(critical).padStart(2, '0')} danger /></View>
    <View style={[s.caseToolbar, s.caseToolbarResponsive, s.caseToolbarLayer]}><View style={[s.caseSearch, s.caseSearchResponsive]}><Ionicons name="search-outline" size={17} color={C.muted} /><TextInput value={search} onChangeText={changeSearch} placeholder="Search by Case ID or Title..." placeholderTextColor={C.muted} style={s.caseSearchInput} accessibilityLabel="Search cases" />{search ? <Pressable onPress={() => changeSearch('')} accessibilityLabel="Clear search"><Ionicons name="close-circle" size={17} color={C.muted} /></Pressable> : null}</View><View style={s.filterControlWrap}><Pressable accessibilityRole="button" accessibilityState={{ expanded: openMenu === 'status' }} style={[s.selectControl, s.selectControlResponsive, openMenu === 'status' && s.selectControlOpen]} onPress={() => setOpenMenu(openMenu === 'status' ? null : 'status')}><Ionicons name="options-outline" size={16} color={C.muted} /><Text style={s.selectText}>{filter === 'All' ? 'All statuses' : filter}</Text><Ionicons name={openMenu === 'status' ? 'chevron-up' : 'chevron-down'} size={15} color={C.muted} /></Pressable>{openMenu === 'status' && <View style={s.filterMenu}>{filters.map(option => <Pressable key={option} accessibilityRole="menuitem" onPress={() => { changeFilter(option); setOpenMenu(null); }} style={[s.filterOption, filter === option && s.filterOptionActive]}><Text style={[s.filterOptionText, filter === option && s.filterOptionTextActive]}>{option === 'All' ? 'All statuses' : option}</Text>{filter === option && <Ionicons name="checkmark" size={16} color={C.green} />}</Pressable>)}</View>}</View><View style={s.filterControlWrap}><Pressable accessibilityRole="button" accessibilityState={{ expanded: openMenu === 'category' }} style={[s.selectControl, s.selectControlResponsive, openMenu === 'category' && s.selectControlOpen]} onPress={() => setOpenMenu(openMenu === 'category' ? null : 'category')}><Text style={s.selectText}>{category}</Text><Ionicons name={openMenu === 'category' ? 'chevron-up' : 'chevron-down'} size={15} color={C.muted} /></Pressable>{openMenu === 'category' && <View style={s.filterMenu}>{categories.map(option => <Pressable key={option} accessibilityRole="menuitem" onPress={() => { setCategory(option); setPage(1); setOpenMenu(null); }} style={[s.filterOption, category === option && s.filterOptionActive]}><Text style={[s.filterOptionText, category === option && s.filterOptionTextActive]} numberOfLines={1}>{option}</Text>{category === option && <Ionicons name="checkmark" size={16} color={C.green} />}</Pressable>)}</View>}</View><Pressable style={[s.exportButton, s.exportButtonResponsive]} accessibilityRole="button" onPress={() => exportReports(filtered)}><Ionicons name="download-outline" size={16} color={C.ink} /><Text style={s.exportText}>Export Data</Text></Pressable></View>
    {notice ? <Info text={notice} /> : null}
    {filter !== 'All' || category !== 'All categories' || search ? <Pressable onPress={clearAll} style={s.clearFilters}><Ionicons name="close-circle-outline" size={15} color={C.green} /><Text style={s.clearFiltersText}>Clear active filters</Text></Pressable> : null}
    {error ? <ErrorState message={error} /> : loading ? <Loading label="Loading reports…" /> : filtered.length ? <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={s.caseTableScroll}><CaseTableInteractive reports={pageReports} total={filtered.length} page={currentPage} pageCount={pageCount} onPageChange={setPage} openReport={openReport} /></ScrollView> : <Empty icon="search-outline" title="No matching reports" text="Try another search term or status filter." />}
  </>;
}

function CaseTableInteractive({ reports, total, page, pageCount, onPageChange, openReport }: { reports: Report[]; total: number; page: number; pageCount: number; onPageChange: (page: number) => void; openReport: (r: Report) => void }) {
  return <View style={s.caseTable}><View style={s.caseTableHeader}><Text style={[s.caseHeaderText, s.caseCheckColumn]}>□</Text><Text style={[s.caseHeaderText, s.caseIdColumn]}>Tracking ID ↕</Text><Text style={[s.caseHeaderText, s.caseTitleColumn]}>Case Title</Text><Text style={[s.caseHeaderText, s.caseCategoryColumn]}>Category</Text><Text style={[s.caseHeaderText, s.caseStatusColumn]}>Status</Text><Text style={[s.caseHeaderText, s.casePriorityColumn]}>Priority</Text><Text style={[s.caseHeaderText, s.caseAssigneeColumn]}>Assignee</Text><Text style={[s.caseHeaderText, s.caseActionsColumn]}>Actions</Text></View>{reports.map(report => <CaseRow key={report.id} report={report} onPress={() => openReport(report)} />)}<View style={s.caseTableFooter}><Text style={s.caseFooterText}>Showing <Text style={s.caseFooterStrong}>{reports.length}</Text> of <Text style={s.caseFooterStrong}>{total}</Text> results</Text><View style={s.pagination}><Pressable accessibilityRole="button" accessibilityLabel="Previous page" disabled={page <= 1} onPress={() => onPageChange(page - 1)} style={[s.pageButton, page <= 1 && s.disabled]}><Ionicons name="chevron-back" size={14} color={C.muted} /></Pressable><View style={s.pageCurrent}><Text style={s.pageCurrentText}>{page}</Text></View><Text style={s.pageNumber}>of {pageCount}</Text><Pressable accessibilityRole="button" accessibilityLabel="Next page" disabled={page >= pageCount} onPress={() => onPageChange(page + 1)} style={[s.pageButton, page >= pageCount && s.disabled]}><Ionicons name="chevron-forward" size={14} color={C.muted} /></Pressable></View></View></View>;
}

function Reports({ reports, total, summary, loading, error, filter, setFilter, search, setSearch, openReport }: { reports: Report[]; total: number; summary: Summary; loading: boolean; error: string; filter: Filter; setFilter: (f: Filter) => void; search: string; setSearch: (v: string) => void; openReport: (r: Report) => void }) {
  const [category, setCategory] = useState('All categories');
  const categories = ['All categories', ...Array.from(new Set(reports.map(r => r.category).filter(Boolean)))];
  const filtered = category === 'All categories' ? reports : reports.filter(r => r.category === category);
  const pendingAssignment = reports.filter(r => r.status === 'Submitted' && !r.assignedInspector).length;
  const activeInvestigations = reports.filter(r => ['Under Review', 'Verified', 'Assigned'].includes(r.status)).length;
  const critical = reports.filter(r => !['Resolved', 'Rejected'].includes(r.status) && priorityFor(r) === 'Critical').length;
  const clearAll = () => { setSearch(''); setFilter('All'); setCategory('All categories'); };
  return <>
    <View style={s.caseHeading}><View style={s.headingCopy}><Text style={s.caseTitle}>Case Management</Text><Text style={s.caseSubtitle}>Oversee, assign, and track all citizen-reported cases within the Ministry jurisdiction.</Text></View><Pressable accessibilityRole="button" style={s.createCase}><Ionicons name="add" size={17} color={C.white} /><Text style={s.createCaseText}>Create Report</Text></Pressable></View>
    <View style={s.caseStats}><CaseStat icon="documents-outline" label="Total cases" value={summary.total} /><CaseStat icon="person-add-outline" label="Pending assignment" value={pendingAssignment} /><CaseStat icon="location-outline" label="Active investigations" value={activeInvestigations} /><CaseStat icon="warning-outline" label="Critical escalations" value={String(critical).padStart(2, '0')} danger /></View>
    <View style={s.caseToolbar}><View style={s.caseSearch}><Ionicons name="search-outline" size={17} color={C.muted} /><TextInput value={search} onChangeText={setSearch} placeholder="Search by Case ID or Title..." placeholderTextColor={C.muted} style={s.caseSearchInput} accessibilityLabel="Search cases" />{search ? <Pressable onPress={() => setSearch('')} accessibilityLabel="Clear search"><Ionicons name="close-circle" size={17} color={C.muted} /></Pressable> : null}</View><Pressable style={s.selectControl} onPress={() => setFilter(filter === 'All' ? 'Submitted' : 'All')}><Ionicons name="options-outline" size={16} color={C.muted} /><Text style={s.selectText}>{filter === 'All' ? 'All statuses' : filter}</Text><Ionicons name="chevron-down" size={15} color={C.muted} /></Pressable><Pressable style={s.selectControl} onPress={() => setCategory(category === 'All categories' ? (categories[1] ?? 'All categories') : 'All categories')}><Text style={s.selectText}>{category}</Text><Ionicons name="chevron-down" size={15} color={C.muted} /></Pressable><Pressable style={s.exportButton} accessibilityRole="button"><Ionicons name="download-outline" size={16} color={C.ink} /><Text style={s.exportText}>Export Data</Text></Pressable></View>
    {filter !== 'All' || category !== 'All categories' || search ? <Pressable onPress={clearAll} style={s.clearFilters}><Ionicons name="close-circle-outline" size={15} color={C.green} /><Text style={s.clearFiltersText}>Clear active filters</Text></Pressable> : null}
    {error ? <ErrorState message={error} /> : loading ? <Loading label="Loading reports…" /> : filtered.length ? <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={s.caseTableScroll}><CaseTable reports={filtered} openReport={openReport} /></ScrollView> : <Empty icon="search-outline" title="No matching reports" text="Try another search term or status filter." />}
  </>;
}

function CaseStat({ icon, label, value, danger = false }: { icon: keyof typeof Ionicons.glyphMap; label: string; value: number | string; danger?: boolean }) { return <View style={s.caseStat}><View style={[s.caseStatIcon, danger && s.caseStatIconDanger]}><Ionicons name={icon} size={18} color={danger ? C.red : C.green} /></View><View><Text style={s.caseStatLabel}>{label.toUpperCase()}</Text><Text style={s.caseStatValue}>{value}</Text></View></View>; }

function priorityFor(report: Report): 'Critical' | 'High' | 'Medium' | 'Low' { const text = `${report.category} ${report.description}`.toLowerCase(); if (report.status === 'Rejected' || /critical|hazard|danger|illegal|structural|emergency/.test(text)) return 'Critical'; if (/urgent|unsafe|violation|damage/.test(text)) return 'High'; if (report.status === 'Resolved') return 'Low'; return 'Medium'; }

function CaseTable({ reports, openReport }: { reports: Report[]; openReport: (r: Report) => void }) { return <View style={s.caseTable}><View style={s.caseTableHeader}><Text style={[s.caseHeaderText, s.caseCheckColumn]}>□</Text><Text style={[s.caseHeaderText, s.caseIdColumn]}>Tracking ID ↕</Text><Text style={[s.caseHeaderText, s.caseTitleColumn]}>Case Title</Text><Text style={[s.caseHeaderText, s.caseCategoryColumn]}>Category</Text><Text style={[s.caseHeaderText, s.caseStatusColumn]}>Status</Text><Text style={[s.caseHeaderText, s.casePriorityColumn]}>Priority</Text><Text style={[s.caseHeaderText, s.caseAssigneeColumn]}>Assignee</Text><Text style={[s.caseHeaderText, s.caseActionsColumn]}>Actions</Text></View>{reports.map(report => <CaseRow key={report.id} report={report} onPress={() => openReport(report)} />)}<View style={s.caseTableFooter}><Text style={s.caseFooterText}>Showing <Text style={s.caseFooterStrong}>{reports.length}</Text> of <Text style={s.caseFooterStrong}>{reports.length}</Text> results</Text><View style={s.pagination}><Pressable style={s.pageButton}><Ionicons name="chevron-back" size={14} color={C.muted} /></Pressable><View style={s.pageCurrent}><Text style={s.pageCurrentText}>1</Text></View><Text style={s.pageNumber}>2</Text><Text style={s.pageNumber}>3</Text><Text style={s.pageNumber}>…</Text><Pressable style={s.pageButton}><Ionicons name="chevron-forward" size={14} color={C.muted} /></Pressable></View></View></View>; }

function CaseRow({ report, onPress }: { report: Report; onPress: () => void }) { const assignee = report.assignedInspector; const priority = priorityFor(report); return <Pressable accessibilityRole="button" accessibilityLabel={`Open case ${ref(report)}`} onPress={onPress} style={({ pressed }) => [s.caseRow, pressed && s.pressed]}><Text style={[s.caseCheckColumn, s.caseCell]}>□</Text><Text style={[s.caseIdColumn, s.caseCell, s.caseIdText]}>{ref(report)}</Text><View style={[s.caseTitleColumn, s.caseTitleCell]}><Text style={s.caseRowTitle} numberOfLines={2}>{report.category}</Text><View style={s.caseLocation}><Ionicons name="location-outline" size={12} color={C.muted} /><Text style={s.caseLocationText} numberOfLines={1}>{location(report)}</Text></View></View><View style={[s.caseCategoryColumn, s.categoryPill]}><Text style={s.categoryPillText}>{report.category}</Text></View><View style={s.caseStatusColumn}><StatusBadge status={report.status} /></View><View style={[s.casePriorityColumn, s.priorityCell]}><View style={[s.priorityDot, priority === 'Critical' && s.priorityCritical, priority === 'High' && s.priorityHigh, priority === 'Low' && s.priorityLow]} /><Text style={s.priorityText}>{priority}</Text></View><View style={[s.caseAssigneeColumn, s.assigneeCell]}>{assignee ? <><View style={s.assigneeAvatar}><Ionicons name="person" size={12} color={C.white} /></View><Text style={s.assigneeText} numberOfLines={1}>{assignee}</Text></> : <><View style={s.unassignedIcon}><Ionicons name="add" size={13} color={C.muted} /></View><Text style={s.unassignedText}>Unassigned</Text></>}</View><View style={[s.caseActionsColumn, s.actionsCell]}><Ionicons name="eye-outline" size={17} color={C.muted} /><Ionicons name="ellipsis-horizontal" size={17} color={C.muted} /></View></Pressable>; }

function StatusBadge({ status }: { status: ReportStatus }) {
  const tone = status === 'Resolved' || status === 'Verified' ? s.badgeSuccess : status === 'Rejected' ? s.badgeDanger : status === 'Assigned' ? s.badgeInfo : s.badgeWarning;
  return <View style={[s.badge, tone]}><Text style={s.badgeText}>{status}</Text></View>;
}

function CompactReportCard({ report, onPress }: { report: Report; onPress: () => void }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={`Open report ${ref(report)}`} onPress={onPress} style={({ pressed }) => [{ flexGrow: 1, flexBasis: 235, maxWidth: 360, minWidth: 235, backgroundColor: C.white, borderWidth: 1, borderColor: C.border, borderRadius: 11, overflow: 'hidden' }, pressed && s.pressed]}>{report.evidenceUrl ? <Image source={{ uri: report.evidenceUrl }} style={{ width: '100%', height: 92, backgroundColor: '#E8ECEE' }} resizeMode="cover" /> : <View style={{ width: '100%', height: 92, backgroundColor: '#E8ECEE', alignItems: 'center', justifyContent: 'center' }}><Ionicons name="image-outline" size={21} color={C.muted} /><Text style={s.emptyText}>No evidence attached</Text></View>}<View style={{ padding: 12 }}><View style={s.reportTop}><Text style={s.reference}>{ref(report)}</Text><StatusBadge status={report.status} /></View><Text style={{ color: C.ink, fontSize: 13, fontWeight: '700', marginTop: 8 }} numberOfLines={1}>{report.category}</Text><Text style={{ color: C.text, fontSize: 11, marginTop: 4 }} numberOfLines={1}>{report.description}</Text><View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginTop: 10 }}><Ionicons name="location-outline" size={13} color={C.muted} /><Text style={s.location} numberOfLines={1}>{location(report)}</Text></View><Text style={{ color: C.green, fontSize: 11, fontWeight: '700', marginTop: 8 }}>Review →</Text></View></Pressable>;
}

function ReportCard({ report, onPress }: { report: Report; onPress: () => void }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={`Open report ${ref(report)}`} accessibilityHint="Opens the complete case record" onPress={onPress} style={({ pressed }) => [s.report, pressed && s.pressed]}>{report.evidenceUrl ? <Image source={{ uri: report.evidenceUrl }} style={s.reportImage} resizeMode="cover" accessibilityLabel="Citizen evidence" /> : <View style={s.reportImageEmpty}><Ionicons name="image-outline" size={25} color={C.muted} /><Text style={s.emptyText}>No evidence attached</Text></View>}<View style={s.reportBody}><View style={s.reportTop}><Text style={s.reference}>{ref(report)}</Text><StatusBadge status={report.status} /></View><Text style={s.reportTitle}>{report.category}</Text><Text style={s.description} numberOfLines={2}>{report.description}</Text><View style={s.meta}><Ionicons name="calendar-outline" size={14} color={C.muted} /><Text style={s.metaText}>{date(report)}</Text></View><View style={s.reportBottom}><View style={s.locationRow}><Ionicons name="location-outline" size={14} color={C.muted} /><Text style={s.location} numberOfLines={1}>{location(report)}</Text></View><Text style={s.open}>Review →</Text></View></View></Pressable>;
}

function MapPage({ reports, openReport }: { reports: Report[]; openReport: (r: Report) => void }) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const located = reports.filter(r => r.latitude != null && r.longitude != null);
  const selected = located.find(r => r.id === selectedId) ?? null;
  return <><Heading eyebrow="GIS MONITORING" title="Reported activity map" subtitle="Review cases with verified coordinates and inspect their evidence." /><Info text={`${located.length} report${located.length === 1 ? '' : 's'} currently have usable coordinates.`} /><View style={s.mapLayout}><View style={s.mapWrap}><OsmMap height={520} reports={reports} /></View><View style={s.locationPanel}><Text style={s.sectionTitle}>Mapped cases</Text><Text style={s.sectionHint}>Select a case to preview it.</Text>{located.length ? located.map(r => <Pressable key={r.id} onPress={() => setSelectedId(r.id)} style={[s.locationTag, selectedId === r.id && s.locationTagActive]}><Ionicons name="location" size={18} color={r.status === 'Resolved' ? C.green : C.red} /><View style={s.headingCopy}><Text style={s.locationTitle} numberOfLines={1}>{r.category}</Text><Text style={s.locationMeta}>{ref(r)} · {r.status}</Text></View></Pressable>) : <Empty compact icon="location-outline" title="No mapped cases" text="Reports with coordinates will appear here." />}{selected && <View style={s.preview}>{selected.evidenceUrl ? <Image source={{ uri: selected.evidenceUrl }} style={s.previewImage} resizeMode="cover" /> : <View style={s.previewEmpty}><Ionicons name="image-outline" size={21} color={C.muted} /><Text style={s.emptyText}>No evidence attached</Text></View>}<Text style={s.previewTitle}>{selected.category}</Text><Text style={s.previewId}>{ref(selected)} · {selected.status}</Text><Pressable onPress={() => openReport(selected)} style={s.primarySmall}><Text style={s.primaryText}>Open complete case</Text></Pressable></View>}</View></View><Info text="Coordinates are restricted to authorised officials. Avoid reproducing exact locations in public exports." /></>;
}

function MapInteractive({ reports, openReport }: { reports: Report[]; openReport: (r: Report) => void }) {
  const [scope, setScope] = useState<'All' | 'Active' | 'Resolved'>('All');
  const scoped = reports.filter(r => r.status !== 'Draft' && (scope === 'All' || (scope === 'Resolved' ? r.status === 'Resolved' : !['Resolved', 'Rejected'].includes(r.status))));
  const located = scoped.filter(r => r.latitude != null && r.longitude != null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = located.find(r => r.id === selectedId) ?? null;
  return <><Heading eyebrow="GIS MONITORING" title="Reported activity map" subtitle="Review cases with verified coordinates and inspect their evidence." /><Info text={`${located.length} mapped case${located.length === 1 ? '' : 's'} in the ${scope.toLowerCase()} view.`} /><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 14 }}><Text style={s.sectionHint}>Map scope</Text>{(['All', 'Active', 'Resolved'] as const).map(item => <Pressable key={item} onPress={() => { setScope(item); setSelectedId(null); }} style={[s.filter, scope === item && s.filterActive]}><Text style={[s.filterText, scope === item && s.filterTextActive]}>{item}</Text></Pressable>)}</View><View style={s.mapLayout}><View style={s.mapWrap}><OsmMap height={520} reports={scoped} /></View><View style={s.locationPanel}><Text style={s.sectionTitle}>Mapped cases</Text><Text style={s.sectionHint}>Select a case to preview it.</Text>{located.length ? located.map(r => <Pressable key={r.id} onPress={() => setSelectedId(r.id)} style={[s.locationTag, selectedId === r.id && s.locationTagActive]}><Ionicons name="location" size={18} color={r.status === 'Resolved' ? C.green : C.red} /><View style={s.headingCopy}><Text style={s.locationTitle} numberOfLines={1}>{r.category}</Text><Text style={s.locationMeta}>{ref(r)} · {r.status}</Text></View></Pressable>) : <Empty compact icon="location-outline" title="No mapped cases" text="Reports with coordinates will appear here." />}{selected && <View style={s.preview}>{selected.evidenceUrl ? <Image source={{ uri: selected.evidenceUrl }} style={s.previewImage} resizeMode="cover" /> : <View style={s.previewEmpty}><Ionicons name="image-outline" size={21} color={C.muted} /><Text style={s.emptyText}>No evidence attached</Text></View>}<Text style={s.previewTitle}>{selected.category}</Text><Text style={s.previewId}>{ref(selected)} · {selected.status}</Text><Pressable onPress={() => openReport(selected)} style={s.primarySmall}><Text style={s.primaryText}>Open complete case</Text></Pressable></View>}</View></View><Info text="Coordinates are restricted to authorised officials. Avoid reproducing exact locations in public exports." /></>;
}

function Analytics({ reports, summary, openReport }: { reports: Report[]; summary: Summary; openReport: (r: Report) => void }) { const [active, setActive] = useState<Filter>('All'); const statuses: Array<[CaseStatus, string]> = [['Submitted', C.gold], ['Under Review', '#D18B28'], ['Verified', C.green], ['Assigned', '#28689C'], ['Resolved', C.green], ['Rejected', C.red]]; const related = active === 'All' ? reports : reports.filter(r => r.status === active); const openCases = reports.filter(r => !['Draft', 'Resolved', 'Rejected'].includes(r.status)).length; const resolutionRate = reports.length ? Math.round((summary.counts.Resolved ?? 0) / reports.length * 100) : 0; const categories = Array.from(new Set(reports.map(r => r.category))).slice(0, 4); return <><View style={s.analyticsHero}><Text style={s.analyticsEyebrow}>ANALYST COMMAND OVERVIEW</Text><Text style={s.analyticsTitle}>System intelligence and workload distribution analytics.</Text><View style={s.analyticsActions}><Pressable style={s.analyticsRefresh}><Ionicons name="refresh-outline" size={15} color={C.text} /><Text style={s.analyticsActionText}>Refresh Data</Text></Pressable><Pressable style={s.analyticsExport}><Ionicons name="download-outline" size={15} color={C.white} /><Text style={s.analyticsExportText}>Export Executive Report</Text></Pressable></View></View><View style={s.analyticsFilters}><Text style={s.analyticsFilter}>Last 30 Days⌄</Text><Text style={s.analyticsFilter}>All Districts⌄</Text><Text style={s.analyticsFilter}>All Priorities⌄</Text><Text style={s.analyticsFilterHint}>Filter by Investigator...</Text><Text style={s.analyticsClear}>Clear Filters</Text></View><View style={s.analyticsKpis}><AnalyticsKpi icon="documents-outline" label="Total reports" value={summary.total} change="+12.5%" /><AnalyticsKpi icon="time-outline" label="Open cases" value={openCases} change="-2.4%" danger /><AnalyticsKpi icon="warning-outline" label="Overdue inspections" value={summary.counts.Assigned ?? 0} change="+5.1%" /><AnalyticsKpi icon="checkmark-circle-outline" label="Avg resolution" value={resolutionRate + '%'} change="-12.0%" danger /></View><View style={s.analyticsTopGrid}><View style={s.analyticsTrendCard}><Text style={s.analyticsPanelTitle}>System Load Trends</Text><Text style={s.analyticsPanelHint}>Incoming reports vs completed resolutions over time</Text><View style={s.lineChart}>{[45,52,48,60,55,66,58].map((height,i)=><View key={i} style={s.linePoint}><View style={[s.lineIncoming,{height}]} /><View style={[s.lineResolved,{height:Math.max(18,height-12)}]} /></View>)}</View><View style={s.chartLegend}><LegendDot color="#0D2E68" label="Incoming Reports" /><LegendDot color={C.green} label="Resolved Cases" /></View></View><View style={s.workloadCard}><Text style={s.analyticsPanelTitle}>Workload Status</Text><Text style={s.analyticsPanelHint}>Distribution by lifecycle state</Text><View style={s.workloadRing}><Text style={s.workloadPercent}>{summary.total ? Math.round(openCases / summary.total * 100) + '%' : '0%'}</Text></View>{statuses.slice(0,4).map(([status])=><Text key={status} style={s.workloadRow}>{status}: <Text style={s.workloadValue}>{summary.counts[status] ?? 0} cases</Text></Text>)}</View></View><View style={s.analyticsMidGrid}><View style={s.analyticsMapCard}><Text style={s.analyticsPanelTitle}>GIS Incident Concentration</Text><Text style={s.analyticsPanelHint}>Reported incidents across monitored sectors</Text><View style={s.analyticsMiniMap}><OsmMap height={260} reports={reports} /></View></View><View style={s.resourceCard}><Text style={s.analyticsPanelTitle}>Resource Allocation by Category</Text><Text style={s.analyticsPanelHint}>Cases requiring specific expertise</Text>{categories.map((category,i)=><View key={category} style={s.resourceRow}><Text style={s.resourceLabel}>{category}</Text><View style={s.resourceTrack}><View style={[s.resourceFill,{width:'70%',backgroundColor:[C.dark,C.green,C.red,'#1680C4'][i]}]} /></View></View>)}</View></View><Text style={s.analyticsSectionTitle}>{active === 'All' ? 'Cases by lifecycle status' : active + ' cases'}</Text>{related.length ? <View style={s.reportGrid}>{related.map(r=><ReportCard key={r.id} report={r} onPress={()=>openReport(r)} />)}</View> : <Empty icon="stats-chart-outline" title="No cases in this category" text="Select another status to inspect its reports." />}</>; } function AnalyticsKpi({ icon, label, value, change, danger = false }: { icon: keyof typeof Ionicons.glyphMap; label: string; value: number | string; change: string; danger?: boolean }) { return <View style={s.analyticsKpi}><Ionicons name={icon} size={20} color={danger ? C.red : C.green} /><Text style={s.analyticsKpiLabel}>{label.toUpperCase()}</Text><Text style={s.analyticsKpiValue}>{value}</Text><Text style={[s.analyticsKpiChange, danger && s.analyticsDanger]}>{change} vs previous period</Text></View>; }
  /* const [active, setActive] = useState<Filter>('All');
  const statuses: Array<[CaseStatus, string]> = [['Submitted', C.gold], ['Under Review', '#D18B28'], ['Verified', C.green], ['Assigned', '#28689C'], ['Resolved', C.green], ['Rejected', C.red]];
  const related = active === 'All' ? reports : reports.filter(r => r.status === active);
  return <><Heading eyebrow="PERFORMANCE" title="Case performance" subtitle="Understand Ministry workload, progress and resolution outcomes." /><Info text="Select a status to inspect the cases contributing to each workload category." /><Stats summary={summary} /><View style={s.analytics}><Text style={s.sectionTitle}>Case status distribution</Text>{statuses.map(([status, color]) => { const amount = summary.counts[status] ?? 0; const percentage = reports.length ? amount / reports.length * 100 : 0; return <Pressable key={status} onPress={() => setActive(active === status ? 'All' : status)} style={[s.analyticsRow, active === status && s.analyticsActive]}><Text style={s.analyticsLabel}>{status}</Text><View style={s.barTrack}>{percentage > 0 && <View style={[s.bar, { width: `${percentage}%`, backgroundColor: color }]} />}</View><Text style={s.analyticsValue}>{amount} · {percentage.toFixed(0)}%</Text></Pressable>; })}</View><Text style={s.sectionTitle}>{active === 'All' ? 'All current cases' : `${active} cases`}</Text>{related.length ? <View style={s.reportGrid}>{related.map(r => <ReportCard key={r.id} report={r} onPress={() => openReport(r)} />)}</View> : <Empty icon="stats-chart-outline" title="No cases in this category" text="Select another status to inspect its reports." />}</>;
} */

function AnalyticsDashboard({ reports, summary, openReport, navigate }: { reports: Report[]; summary: Summary; openReport: (r: Report) => void; navigate: (page: Page) => void }) {
  const [active, setActive] = useState<Filter>('All');
  const [period, setPeriod] = useState('Last 30 days');
  const statuses: Array<[CaseStatus, string]> = [['Submitted', C.gold], ['Under Review', '#D18B28'], ['Verified', C.green], ['Assigned', '#28689C'], ['Resolved', C.green], ['Rejected', C.red]];
  const periodDays = period === 'Last 7 days' ? 7 : 30;
  const cutoff = Date.now() - periodDays * 24 * 60 * 60 * 1000;
  const periodReports = reports.filter(r => { const created = r.createdAt?.toDate?.(); return created instanceof Date && !Number.isNaN(created.getTime()) ? created.getTime() >= cutoff : true; });
  const periodCounts = periodReports.reduce<Record<string, number>>((counts, report) => { counts[report.status] = (counts[report.status] ?? 0) + 1; return counts; }, {});
  const activeReports = periodReports.filter(r => r.status !== 'Draft');
  const openCases = activeReports.filter(r => !['Resolved', 'Rejected'].includes(r.status)).length;
  const overdue = periodCounts.Assigned ?? 0;
  const resolutionRate = activeReports.length ? Math.round((periodCounts.Resolved ?? 0) / activeReports.length * 100) : 0;
  const related = (active === 'All' ? activeReports : activeReports.filter(r => r.status === active)).slice(0, 6);
  const maxStatus = Math.max(1, ...statuses.map(([status]) => periodCounts[status] ?? 0));
  const categoryCounts = Array.from(new Set(activeReports.map(r => r.category))).map(category => ({ category, count: activeReports.filter(r => r.category === category).length })).sort((a, b) => b.count - a.count).slice(0, 4);
  return <>
    <View style={s.analyticsHero}><Text style={s.analyticsEyebrow}>ANALYST COMMAND OVERVIEW</Text><Text style={s.analyticsTitle}>System intelligence and workload distribution</Text><Text style={s.analyticsPanelHint}>A controlled view of report volume, investigation pressure and resolution performance.</Text><View style={s.analyticsActions}><Pressable onPress={() => setPeriod(period === 'Last 30 days' ? 'Last 7 days' : 'Last 30 days')} style={s.analyticsRefresh}><Ionicons name="calendar-outline" size={15} color={C.text} /><Text style={s.analyticsActionText}>{period}</Text></Pressable><Pressable onPress={() => exportReports(activeReports)} style={s.analyticsExport}><Ionicons name="download-outline" size={15} color={C.white} /><Text style={s.analyticsExportText}>Export Executive Report</Text></Pressable></View></View>
    <View style={s.analyticsKpis}><AnalyticsKpi icon="documents-outline" label="Total reports" value={periodReports.length} change={period} /><AnalyticsKpi icon="time-outline" label="Open cases" value={openCases} change="Requires action" danger={openCases > 0} /><AnalyticsKpi icon="warning-outline" label="Pending assignment" value={overdue} change="Field allocation" danger={overdue > 0} /><AnalyticsKpi icon="checkmark-circle-outline" label="Resolution rate" value={`${resolutionRate}%`} change={period} /></View>
    <View style={s.analyticsTopGrid}><View style={s.analyticsTrendCard}><View style={s.commandSectionHeader}><View><Text style={s.analyticsPanelTitle}>Workload status</Text><Text style={s.analyticsPanelHint}>Select a lifecycle state to inspect its cases.</Text></View><Pressable onPress={() => navigate('Reports')}><Text style={s.link}>Open queue</Text></Pressable></View>{statuses.map(([status, color]) => { const amount = periodCounts[status] ?? 0; return <Pressable key={status} onPress={() => setActive(active === status ? 'All' : status)} style={[s.analyticsRow, active === status && s.analyticsActive]}><Text style={s.analyticsLabel}>{status}</Text><View style={s.barTrack}><View style={[s.bar, { width: `${Math.max(3, amount / maxStatus * 100)}%`, backgroundColor: color }]} /></View><Text style={s.analyticsValue}>{amount}</Text></Pressable>; })}</View><View style={s.workloadCard}><Text style={s.analyticsPanelTitle}>Resolution health</Text><Text style={s.analyticsPanelHint}>Resolved cases compared with active workload.</Text><View style={s.workloadRing}><Text style={s.workloadPercent}>{resolutionRate}%</Text><Text style={s.workloadRow}>resolved</Text></View><LegendDot color={C.green} label={`${periodCounts.Resolved ?? 0} resolved`} /><LegendDot color={C.red} label={`${openCases} open`} /><LegendDot color={C.muted} label={`${periodCounts.Rejected ?? 0} rejected`} /></View></View>
    <View style={s.analyticsMidGrid}><View style={s.analyticsMapCard}><View style={s.commandSectionHeader}><View><Text style={s.analyticsPanelTitle}>GIS incident concentration</Text><Text style={s.analyticsPanelHint}>Mapped cases available for operational review.</Text></View><Pressable onPress={() => navigate('Map')}><Text style={s.link}>Open map</Text></Pressable></View><View style={s.analyticsMiniMap}><OsmMap height={260} reports={activeReports} /></View></View><View style={s.resourceCard}><Text style={s.analyticsPanelTitle}>Resource allocation</Text><Text style={s.analyticsPanelHint}>Categories requiring Ministry attention.</Text>{categoryCounts.length ? categoryCounts.map(({ category, count }, index) => <Pressable key={category} onPress={() => setSearchCategory(category, navigate)} style={s.resourceRow}><View style={{ flexDirection: 'row', justifyContent: 'space-between' }}><Text style={s.resourceLabel}>{category}</Text><Text style={s.resourceLabel}>{count}</Text></View><View style={s.resourceTrack}><View style={[s.resourceFill, { width: `${Math.max(8, count / Math.max(1, categoryCounts[0]?.count ?? 1) * 100)}%`, backgroundColor: [C.dark, C.green, C.red, '#1680C4'][index] }]} /></View></Pressable>) : <Empty compact icon="bar-chart-outline" title="No category data" text="Reports will appear here as they arrive." />}</View></View>
    <View style={s.rowTitle}><View><Text style={s.sectionTitle}>{active === 'All' ? 'Recent active cases' : `${active} cases`}</Text><Text style={s.sectionHint}>Preview limited to six cases for a responsive command view.</Text></View><Pressable onPress={() => navigate('Reports')}><Text style={s.link}>View all reports</Text></Pressable></View>{related.length ? <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 12 }}>{related.map(r => <CompactReportCard key={r.id} report={r} onPress={() => openReport(r)} />)}</View> : <Empty icon="stats-chart-outline" title="No cases in this category" text="Select another lifecycle state to inspect its reports." />}
  </>;
}

function setSearchCategory(category: string, navigate: (page: Page) => void) { navigate('Reports'); void category; }

function SettingsDashboardLegacy({ adminId, adminEmail, role, navigate }: { adminId: string; adminEmail?: string | null; role: Exclude<AdminRole, 'citizen'>; navigate: (page: Page) => void }) {
  const masked = adminId.length > 12 ? `${adminId.slice(0, 6)}••••${adminId.slice(-4)}` : adminId;
  const roleLabel = role === 'admin' ? 'Administrator' : 'Investigator / Field officer';
  const accountLabel = adminEmail?.trim() || 'Email unavailable';
  const statusStyle = { flexDirection: 'row' as const, alignItems: 'center' as const, gap: 7, marginTop: 18, backgroundColor: C.soft, padding: 10, borderRadius: 8 };
  const actionStyle = { minHeight: 44, borderTopWidth: 1 as const, borderTopColor: C.border, flexDirection: 'row' as const, alignItems: 'center' as const, gap: 9, paddingVertical: 10 };
  return <><Heading eyebrow="ADMINISTRATION" title="Ministry settings" subtitle="Review identity, protection controls and workspace guidance." /><Info text="Access is enforced by Firebase Authentication and Security Rules. Settings shown here are operational information, not permission controls." /><View style={s.settingsGrid}><View style={s.settingsCard}><Ionicons name="shield-checkmark-outline" size={25} color={C.green} /><Text style={s.sectionTitle}>Identity and access</Text><Setting label="Workspace role" value={roleLabel} /><Setting label="Signed-in account" value={roleLabel} /><Setting label="Account ID" value={masked} /><View style={statusStyle}><View style={s.liveDot} /><Text style={{ color: C.green, fontSize: 11, fontWeight: '700' }}>Authenticated session active</Text></View></View><View style={s.settingsCard}><Ionicons name="server-outline" size={25} color={C.green} /><Text style={s.sectionTitle}>System information</Text><Setting label="Application" value="LandWatch ZW" /><Setting label="Workspace" value="Ministry operations centre" /><Setting label="Data handling" value="Citizen evidence is restricted to authorised officials." /><Setting label="Report lifecycle" value="Submitted → Review → Assignment → Resolution" /></View></View><View style={s.settingsGrid}><View style={s.settingsCard}><Ionicons name="options-outline" size={25} color={C.green} /><Text style={s.sectionTitle}>Operational safeguards</Text><Setting label="Case visibility" value={role === 'admin' ? 'All Ministry cases' : 'Assigned cases only'} /><Setting label="Final decisions" value="Resolution and rejection require an official note." /><Setting label="Location privacy" value="Exact coordinates are restricted to authorised officials." /></View><View style={s.settingsCard}><Ionicons name="navigate-outline" size={25} color={C.green} /><Text style={s.sectionTitle}>Quick actions</Text><Pressable onPress={() => navigate('Reports')} style={actionStyle}><Ionicons name="document-text-outline" size={17} color={C.green} /><Text style={{ flex: 1, color: C.text, fontSize: 12, fontWeight: '700' }}>Open case management</Text><Ionicons name="arrow-forward" size={16} color={C.green} /></Pressable><Pressable onPress={() => navigate('Map')} style={actionStyle}><Ionicons name="map-outline" size={17} color={C.green} /><Text style={{ flex: 1, color: C.text, fontSize: 12, fontWeight: '700' }}>Open GIS map</Text><Ionicons name="arrow-forward" size={16} color={C.green} /></Pressable><Pressable onPress={() => navigate('Analytics')} style={actionStyle}><Ionicons name="bar-chart-outline" size={17} color={C.green} /><Text style={{ flex: 1, color: C.text, fontSize: 12, fontWeight: '700' }}>Open analytics</Text><Ionicons name="arrow-forward" size={16} color={C.green} /></Pressable></View></View></>;
}

